# Implement solution based on pattern: find marker (unique/small group), copy pattern 
# centered at each marker position

def solve_422ee742(grid):
    """
    ARC task transformation:
    1. Background = most frequent value
    2. Marker = value appearing 1-3 times (small connected group or scattered)
    3. Pattern = remaining non-background cells (forming a larger shape)
    4. Copy pattern centered at each marker position
    """
    if not grid or not grid[0]:
        return grid

    height, width = len(grid), len(grid[0])
    bg = most_frequent(grid)

    # Collect non-background cells grouped by value
    ncells = {}
    for r in range(height):
        for c in range(width):
            if grid[r][c] != bg:
                v = grid[r][c]
                if v not in ncells:
                    ncells[v] = []
                ncells[v].append((r, c))

    # Identify marker value (appears few times other values appear more)
    # or identify pattern (forms a distinct shape vs scattered)

    # Heuristic: smallest group = marker, rest = pattern
    sorted_vals = sorted(ncells.items(), key=lambda x: len(x[1]))
    if len(sorted_vals) >= 1:
        marker_value = sorted_vals[0][0]
    else:
        marker_value = None

    if len(sorted_vals) >= 2:
        pattern_value = sorted_vals[1][0]
    else:
        pattern_value = None

    # Get marker positions and pattern positions
    if marker_value:
        markers = ncells[marker_value]
    else:
        markers = []

    if pattern_value:
        pattern_cells = [(r, c) for r, c in ncells[pattern_value]]
    else:
        pattern_cells = []

    if not markers:
        return grid

    if not pattern_cells:
        return grid

    # Compute pattern bounding box for centered placement
    rmin, rmax = min(r for r, c in pattern_cells), max(r for r, c in pattern_cells)
    cmin, cmax = min(c for r, c in pattern_cells), max(c for r, c in pattern_cells)

    # Create output grid with background
    output = [[bg for _ in range(width)] for _ in range(height)]

    # Place pattern centered at each marker
    for mr, mc in markers:
        # Compute offset to center pattern at marker
        # Pattern center = ((rmin+rmax)/2, (cmin+cmax)/2)
        # Marker should be at pattern center in output => offset = (mr - rmin, mc - cmin)

        # Actually, pattern gets centered at marker row and column
        # So pattern cell (r, c) goes to (mr + r - rmin, mc + c - cmin)

        for pr, pc in pattern_cells:
            nr, nc = mr + (pr - rmin), mc + (pc - cmin)
            if 0 <= nr < height and 0 <= nc < width:
                output[nr][nc] = grid[pr][pc]  # Copy original value

    return output

